steps.instructions:
Add functions to aggregate data from multiple API endpoints and cache results locally:

```python
def fetch_all_data():
    """Fetch users, posts, and comments. Cache to local files."""
    cache_dir = Path("cache")
    cache_dir.mkdir(exist_ok=True)

    endpoints = {
        "users": "https://jsonplaceholder.typicode.com/users",
        "posts": "https://jsonplaceholder.typicode.com/posts",
        "comments": "https://jsonplaceholder.typicode.com/comments",
    }

    data = {}
    for name, url in endpoints.items():
        cache_file = cache_dir / f"{name}.json"

        # Try cache first
        if cache_file.exists():
            print(f"  Loading {name} from cache...")
            data[name] = json.loads(cache_file.read_text(encoding="utf-8"))
        else:
            # Fetch from API
            print(f"  Fetching {name} from API...")
            try:
                response = requests.get(url, timeout=10)
                response.raise_for_status()
                data[name] = response.json()
                # Save to cache
                cache_file.write_text(
                    json.dumps(data[name], indent=2),
                    encoding="utf-8"
                )
            except Exception as e:
                print(f"  Error fetching {name}: {e}")
                data[name] = []

    print(f"\nData loaded:")
    for name, items in data.items():
        print(f"  {name}: {len(items)} records")

    return data


def build_summary(data):
    """Build a summary combining users, posts, and comments."""
    users = {u["id"]: u["name"] for u in data["users"]}

    # Count posts per user
    post_counts = {}
    for post in data["posts"]:
        uid = post["userId"]
        post_counts[uid] = post_counts.get(uid, 0) + 1

    # Count comments per post
    comment_counts = {}
    for comment in data["comments"]:
        pid = comment["postId"]
        comment_counts[pid] = comment_counts.get(pid, 0) + 1

    # Build summary
    summary = []
    for uid, name in users.items():
        user_posts = [p for p in data["posts"] if p["userId"] == uid]
        user_comments = sum(comment_counts.get(p["id"], 0) for p in user_posts)
        summary.append({
            "name": name,
            "posts": post_counts.get(uid, 0),
            "comments_received": user_comments,
        })

    return sorted(summary, key=lambda x: x["posts"], reverse=True)


# Test
data = fetch_all_data()
summary = build_summary(data)
print("\nUser Activity Summary:")
print(f"  {'Name':<25} {'Posts':>5} {'Comments':>10}")
print("  " + "-" * 42)
for item in summary[:5]:
    print(f"  {item['name']:<25} {item['posts']:>5} {item['comments_received']:>10}")
```

Run the script twice — the second time should load from cache.
